INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Incremento de Renta', '5', 'Sexta', 'AJUSTE DE LA RENTA', E'- The rent can be increased as specified in Section 6 of the contract, starting from the property''s opening date.\n- The increase is based on changes in the National Consumer Price Index (INPC) published by INEGI.\n- The first rent adjustment occurs 13 months after the date mentioned in Section 11 of the contract.\n- Until the INPC is published, the tenant continues paying the current rent amount.\n- Once the INPC is available, the rent is adjusted accordingly, and the tenant must pay any differences immediately.\n- After the initial contract term, during the first year of extension, rent is updated using the INPC method plus an additional 10% increase.\n- From the second year of extension onwards, rent adjustments are based solely on the INPC method.', E'Las Partes convienen que la Renta podrá ser incrementada en el periodo que se indica en el Apartado 6 de la Carátula contado a partir de la fecha de apertura del Inmueble, incrementándose de acuerdo con la siguiente mecánica:\nSe tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI) en el Diario Oficial de la Federación (D.O.F), respecto de los 12 (doce) meses anteriores al del incremento. Tratándose del primer ajuste en la Renta, éste se realizará una vez que hubieren transcurrido 13 (trece) meses contados a partir de la fecha referida en el Apartado 11 de la Carátula; en el entendido que hasta en tanto no se publique el índice antes mencionado, la Arrendataria deberá continuar liquidando a la Arrendadora el importe de la Renta con base en los montos estipulados en el presente contrato obligándose a que, una vez publicado el índice en comento, la cantidad a pagar por concepto de la Renta, será ajustada en la proporción que corresponda, debiendo la Arrendataria cubrir dichos incrementos y/o diferencias de manera inmediata.\nUna vez concluida la vigencia inicial del Contrato y sólo para el primer año de prórroga, la renta se actualizará conforme al mecanismo señalado en los párrafos anteriores más un incremento adicional del 10% (diez por ciento). A partir del segundo año de la prórroga, y durante el resto de su vigencia, los ajustes de la renta se realizarán exclusivamente conforme al mecanismo de actualización basado en el INPC establecido en la presente cláusula.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Inversión', '8', 'Décima cuarta', 'DERECHOS DE LA ARRENDATARIA', E'- Build a fenced multi-use court at least 22 meters long and 12 meters wide on the building''s rooftop.\n- The court is for the exclusive use of Colegio Vizcaínas students.\n- Construct a direct access from Vizcaínas plaza to the rooftop.\n- Ensure the access route does not go through the gym or internal parking.', 'Construir una cancha enrejada de usos múltiples de por lo menos 22 mts de largo. por 12 mts.de ancho, en la azotea del edificio para uso exclusivo de los alumnos del Colegio Vizcainas y construir también un acceso directo desde la plaza de Vizcaínas a la azotea del edificio, sin pasar por el gimnasio y estacionamiento interno para que por ese acceso tengan paso los alumnos.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('0c7bd7a5-722a-4010-ac7a-c95ef18dd0e5', 'Lázaro Cárdenas', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Manzana 1 Avenida José María Morelos Esquina Avenida Lázaro Cárdenas', 'Unidad 2.14, Sector 2', 'Lázaro Cárdenas', 'Michoacán', '0000', 'MX', 'Manzana 1 Avenida José María Morelos Esquina Avenida Lázaro Cárdenas, Unidad 2.14, Sector 2, Lázaro Cárdenas, Michoacán 0000', 17.9700279465, -102.2112204789, 'Retail', 'Lifestyle Center', 'Fitness', 'Franchise', 'Soriana Sucursal 003 Lázaro Cárdenas', 2091.13, NULL, NULL, '{"map_marker_color":"#808080","coordinate":"point|17.9700279465|-102.2112204789|accurate","city_state":"Lázaro Cárdenas, Michoacán","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Avenida Constituyentes 1150, Colonia Lomas Altas, Miguel Hidago, C.P. 11950, CDMX,  ","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"TBD","lease_expiration_date":"TBD","lease_renewal_notice":"180 Days Prior","lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":68142,"grid_name":"Lázaro Cárdenas","grid_full_address":"Manzana 1 Avenida José María Morelos Esquina Avenida Lázaro Cárdenas, Unidad 2.14, Sector 2, Lázaro Cárdenas, Michoacán 0000","map_addr_1":"Manzana 1 Avenida José María Morelos Esquina Avenida Lázaro Cárdenas","map_addr_2":"Unidad 2.14, Sector 2","map_city_state_zip":"Lázaro Cárdenas, Michoacán 0000","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-06-01 17:11:24","active_lease_count_over_time":61531,"location_count_over_time":68142,"remaining_rent_liability_over_time":61531}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', '0c7bd7a5-722a-4010-ac7a-c95ef18dd0e5', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Lázaro Cárdenas Sublease: Inmobiliaria Kira, S.A. de C.V.', NULL, true, 'activo', 'Lease', NULL, NULL, NULL, NULL, NULL, false, 1, NULL, 0, NULL, NULL, NULL, 'Send Notice to Renew', NULL, 'Inmobiliaria Kira, S.A. de C.V.', NULL, NULL, 'Avenida Constituyentes 1150, Colonia Lomas Altas, Miguel Hidago, C.P. 11950, CDMX', NULL, NULL, NULL, NULL, 'MX', NULL, NULL, NULL, 120, NULL, NULL, NULL, 865727.82, 'La arrendataria debe pagar al arrendador, en la fecha de entrega del local, un monto equivalente a dos meses de renta ($865,727.82 más IVA). Este pago se aplicará a los primeros dos meses de renta una vez que termine el periodo de gracia o desde que inicie operaciones el negocio, lo que ocurra primero.', NULL, true, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No","rent_commencement_date_original":"TBD","expiration_date_original":"TBD","expiration_date_including_options_original":"TBD"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Domicilio del Contrato', '"Lázaro Cárdenas" con domicilio en la Avenida José María Morelos equina Avenida Lázaro Cárdenas, Manzana 1, unidad 2.14, sector 2, Municipio de Lázaro Cárdenas, Michoacán.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Fecha de Firma del Contrato', '02 de marzo de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Vigencia', '10 años forzosos para ambas partes contados a partir de la Fecha de Entrega Efectiva del Local comercial', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Fecha de entrega del local comercial', 'Las Partes aceptan que la entrega-recepción de la posesión en calidad de subarrendamiento de EL LOCAL COMERCIAL para lo cual se le notificara a LA SUBARRENDATARIA con al menos 30 (treinta) días previos a la fecha de entrega (en lo sucesivo la "Entrega Programada")', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Fecha de inicio de pago de renta', 'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA SUBARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL.', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Base Rent', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- The tenant must start paying rent after the grace period ends or when they begin operations, whichever comes first.\n- The rent will be the higher of the following two options:\n  - A fixed minimum rent of $432,863.91 plus VAT.\n  - 5% of their monthly net income plus VAT (variable rent).', 'La arrendataria deberá pagar, a partir del fin del plazo de gracia o desde que inicie operaciones (lo que ocurra primero), la cantidad que resulte mayor entre; Una renta mínima fija de $432,863.91 más IVA, o El 5% de sus ingresos netos mensuales más IVA (renta variable).');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Common Area Maintenance Charges', '9', 'Séptima', 'CUOTA DE MANTENIMIENTO', E'- La arrendataria debe pagar una Cuota de Mantenimiento cada mes.\n- Esta cuota es el 15% de la renta mínima mensual.\n- Además, se debe agregar el IVA a esta cuota.', 'La arrendataria deberá pagar mensualmente una Cuota de Mantenimiento equivalente al 15% de la renta mínima mensual más IVA');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Late Fees', '9', 'Octava', 'FORMA Y LUGAR DE PAGO DE RENTA', E'- Late interest is calculated using the 28-day TIIE rate multiplied by 3.\n- This interest applies from the due date until the debt is fully paid.', 'Intereses moratorios calculados con base en la TIIE a 28 días multiplicada por 3, desde la fecha en que debió pagarse hasta que se liquide totalmente el adeudo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Extension period', '7', 'Cuarta', 'PLAZO', E'- The tenant can extend the lease for an additional 5 years.\n- The tenant must notify the landlord at least 180 days before the current lease ends.\n- The financial terms of the extension will be negotiated between the tenant and landlord.\n- Any rent increase cannot be more than 12.5% of the current minimum rent.', 'La arrendataria tiene derecho a prorrogar el contrato por 5 años adicionales, notificando al arrendador con al menos 180 días de anticipación, las condiciones económicas de la prórroga se negociarán entre las partes, y cualquier incremento en la renta no podrá exceder el 12.5% de la última Renta Mínima vigente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Incremento de Renta', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- La renta se ajustará cada año.\n- El ajuste se basará en el aumento del Índice Nacional de Precios al Consumidor (INPC).\n- Se considerará la variación de los últimos 12 meses.', 'La renta se ajustará anualmente conforme al incremento del Índice Nacional de Precios al Consumidor (INPC) publicado por el INEGI, considerando la variación de los últimos 12 meses.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Parking', '10', 'Novena', 'OBLIGACIONES DEL ARRENDADOR', E'- Si el centro comercial cobra por estacionamiento, la arrendataria recibirá algunos lugares gratuitos para su personal.\n- Otros empleados, clientes y visitantes deben pagar la tarifa regular.\n- Los clientes de la arrendataria obtienen una tarifa especial de hasta $10 por las primeras 2 horas; después se aplica la tarifa normal.\n- La tarifa especial puede actualizarse cada 24 meses si hay aumentos generales en el centro comercial.', E'Si el centro comercial cobra estacionamiento, las partes acordarán otorgar a la arrendataria cierto número de lugares gratuitos (pensiones o cortesías) para su personal, mientras que el resto de empleados, clientes y visitantes deberán pagar la tarifa vigente.\nAdemás, se otorgará a los clientes de la arrendataria una tarifa preferencial de hasta $10 por las primeras 2 horas; después de ese tiempo aplicará la tarifa normal.\nEsta tarifa preferencial podrá actualizarse cada 24 meses, siempre que haya incrementos generales en el centro comercial.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6b0ec297-30f2-4fbd-bb1b-a5f1b9543078', 'Período para obtener licencias y permisos', '13', 'Décima primera', 'DERECHOS DE LA ARRENDATARIA', E'- If the tenant cannot obtain necessary permits, licenses, or services within 120 days after taking possession of the premises, and it''s not their fault, they can:\n  - End the lease without penalty, and the landlord must refund any payments made.\n  - Agree to an additional 120 days to try to obtain them.\n- The tenant must prove they made the necessary efforts and that the lack of permits is not their fault.\n- Once the landlord is notified, they have up to 60 days to try to obtain the required permits or services.', E'Si dentro de los 120 días posteriores a la entrega del local la arrendataria no obtiene los permisos, licencias o servicios necesarios por causas no imputables a ella, podrá: i) Dar por terminado el contrato sin responsabilidad, obligándose el arrendador a devolver las cantidades pagadas, o\nii) Acordar un plazo adicional de 120 días para obtenerlos.\n\nEsto aplica siempre que la arrendataria demuestre que realizó las gestiones necesarias y que la falta de permisos no es imputable a ella. Adicionalmente, una vez notificado el arrendador, este contará con hasta 60 días para intentar obtener dichos permisos o servicios requeridos.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('0ba57653-512d-47fd-9782-4335d79a3079', 'San Antonio Abad', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '122 y 124 Avenida San Antonio Abad', NULL, 'Tránsito, Cuahutémoc', 'Ciudad de México', '06820', 'MX', '122 y 124 Avenida San Antonio Abad,  Tránsito, Cuahutémoc, Ciudad de México 06820', 19.4169086897, -99.1340204034, 'Retail', 'Lifestyle Center', 'Fitness', NULL, NULL, 2004, NULL, NULL, '{"map_lease_expiration_date":"2037-07-31","map_marker_color":"#808080","coordinate":"point|19.4169086897|-99.1340204034|accurate","city_state":"Tránsito, Cuahutémoc, Ciudad de México","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Rubén Darío 281, Bosques de Chapultepec, C.P. 11580, Alcaldía Miguel Hidalgo, Ciudad de México,  ","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2042-07-31","lease_expiration_date":"2037-07-31","lease_renewal_notice":"30 Days Prior","lease_length_in_months_remaining":130,"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":68149,"grid_name":"San Antonio Abad","grid_full_address":"122 y 124 Avenida San Antonio Abad,  Tránsito, Cuahutémoc, Ciudad de México 06820","map_addr_1":"122 y 124 Avenida San Antonio Abad","map_city_state_zip":"Tránsito, Cuahutémoc, Ciudad de México 06820","grid_brand":"Planet Fitness","location_created_at":"2026-06-01 18:37:00","active_lease_count_over_time":61533,"location_count_over_time":68149,"remaining_rent_liability_over_time":61533}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', '0ba57653-512d-47fd-9782-4335d79a3079', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'San Antonio Abad Lease: Ve Por Mas, S.A. Institución de Banca Múltiple, Grupo Financiero Ve Por Más, como Fiduciaria del Fideicomiso 777 San Antonio Abad (08/01/2027 - 07/31/2037)', NULL, false, 'vencido', 'Lease', NULL, '2027-12-29', '2027-08-01', '2037-07-31', '2047-07-31', false, 2, NULL, 2, NULL, NULL, '2037-07-01', 'Send Notice to Decline', 119, 'Ve Por Mas, S.A. Institución de Banca Múltiple, Grupo Financiero Ve Por Más, como Fiduciaria del Fideicomiso 777 San Antonio Abad', NULL, NULL, 'Rubén Darío 281, Bosques de Chapultepec, C.P. 11580, Alcaldía Miguel Hidalgo, Ciudad de México', NULL, NULL, NULL, NULL, 'MX', NULL, NULL, NULL, 150, NULL, NULL, 491890, 983780, 'Arrendatario entregará al Arrendador, dentro de los 7 (siete) días naturales posteriores a la Fecha de Entrega del Local, junto con el monto por concepto del Depósito en Garantía, un pago adelantado correspondiente a los dos primeros meses de renta el cual se aplicará al primer mes de renta corriente.', NULL, false, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Fecha de Firma del Contrato', '10 de febrero de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Domicilio del Arrendador', 'Rubén Darío No. 281, L-2201, Colonia Bosque de Chapultepec, C.P. 11580, Alcaldía Miguel Hidalgo, Ciudad de México.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Domicilio del Contrato', 'Avenida San Antonio Abad No. 122, Colonia Tránsito, C.P. 06820, Alcaldía Cuauhtémoc, Ciudad de México, que cuenta con una superficie de 1,682 m2 y el predio Avenida San Antonio Abad No. 124, Colonia Tránsito, C.P. 06820, Alcaldía Cuauhtémoc, Ciudad de México, que cuenta con una superficie de 3,825.30 m2', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Pago de Rentas', '6', 'sexta', 'RENTA', E'- Upon the Delivery Date of the Premises, the Parties will review and possibly adjust the Rent amount based on these options:\n  - The rent per square meter should be at least $13.63 USD, or\n  - The rent per square meter should be at least the agreed price in pesos plus inflation from the contract signing date to the Delivery Date.\n- The higher rent amount from these options will be used.\n- The Landlord will provide the Tenant with documentation of the exchange rate published in the Official Gazette of the Federation one day before the Delivery Date.', E'Las Partes acuerdan que al momento de la Fecha de Entrega del Local revisarán y en su caso ajustarán el monto de la Renta de acuerdo con las siguientes opciones:\ni) Que el costo por metro cuadrado de la Renta tenga una equivalencia igual o mayor a $13.63 dólares, o     ii) Que el costo por metro cuadrado de la Renta sea igual o mayor al precio pactado en pesos más la inflación transcurrida desde la fecha de firma del presente Contrato hasta la Fecha de Entrega del Local.\n\nDe las opciones anteriores la Renta se tomará la que resulte mayor. Asimismo, el Arrendador comprobará al Arrendatario documentalmente el tipo de cambio publicado en el Diario Oficial de la Federación un día antes de la Fecha de Entrega del Local.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Incremento de Renta', '7', 'séptima', 'INCREMENTOS', E'- La renta mensual aumentará cada 12 meses.\n- El primer aumento será en enero de 2029, o 12 meses después de la apertura del local, lo que ocurra primero.\n- El aumento se basará en el Índice Nacional de Precios al Consumidor (INPC) de los 12 meses anteriores.\n- Si el INPC no está disponible en el mes del aumento, se usará el índice más reciente.\n- Si el INPC deja de publicarse, se usará un nuevo índice basado en la inflación de EE.UU., acordado por ambas partes.', E'Durante la vigencia del presente Contrato y sus prórrogas, el monto de la Renta Mensual, deberá ser aumentada cada 12 (doce) meses, comenzando con la renta aplicable para el mes de enero de 2029, en el entendido de que dicha fecha deberá coincidir con el cumplimiento de 12 (doce) meses contados desde la Fecha de Apertura del Local Comercial; en caso contrario, la fecha del primer incremento se ajustará para reflejar dicho plazo. \n\nDicho aumento será proporcionalmente igual al aumento en el Índice Nacional de Precios al Consumidor "INPC", que se publica en el Diario Oficial de la Federación, durante el periodo inmediato anterior de 12 (doce) meses. En el supuesto de que en el mes en que se deba realizar el aumento del monto de la Renta Mensual, no sea publicado el índice mencionado en el párrafo anterior, el aumento se hará de conformidad con la publicación más reciente de dicho índice, en forma anualizada, el cual se aplicará al mes en que dicho aumento debió haberse realizado. Ahora bien, en el supuesto de que el índice antes mencionado deje de ser publicado, el aumento se hará de conformidad con un nuevo índice basado en la inflación de los Estados Unidos de América, mismo que deberá ser acordado por las partes.');
